<?php require_once __DIR__.'/../includes/auth.php'; $pageTitle='Categories'; $base='/shop-inventory-management'; $rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll(); require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/sidebar.php'; ?>
<div class="page-heading"><div><h1>Categories</h1><p>Organise your catalogue into clear groups.</p></div><a class="btn primary" href="create.php">＋ Add category</a></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Description</th><th>Products</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No categories created yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['description']?:'—')?></td><td><?=$r['product_count']?></td><td><?=e($r['created_at'])?></td><td class="actions"><a class="btn small" href="edit.php?id=<?=$r['id']?>">Edit</a><form method="post" action="delete.php" class="inline-form" data-confirm="Delete this category? This only works when no products use it."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small danger" type="submit">Delete</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
